#include "GCOutput.h"
#include <stdio.h>
#include <stdlib.h>

/* must match the layout generated by the compiler */
struct Wrap {
  int mark;
  union {
    struct { int member0; } Wrap;
  } value;
};

void Input(int* a) {
  if (scanf("%d", a) == EOF) {
    exit(0);
  }
}

void Output(struct Wrap** o, int* r, struct Wrap** o2) {
  printf("o=%d r=%d o2=%d\n", (*o)->value.Wrap.member0, *r, (*o2)->value.Wrap.member0);
}

int main() {
  ActivateGCOutput();
}
